/// <summary>
/// Defines Telemetry event names logged into AppInsights
/// </summary>
public final class METTelemetryEventNames
{
    public const str ReadyForPricingEvent       = 'SalesOrder.ReadyForPricing';
    public const str OptimizationCompletedEvent = 'SalesOrder.OptimisationCompleted';
    public const str PricingCompletedEvent      = 'SalesOrder.PricingCompleted';
    public const str ReadyForInvoicingEvent     = 'SalesOrder.ReadyForInvoicing';
    public const str PendingProcessing          = 'SalesOrder.PendingProcessing';
    public const str IOMSyncCompleted           = 'SalesOrder.IOMSyncCompleted';
    public const str SOConfirmedEvent           = 'SalesOrder.Confirmation';
    public const str SOPickedEvent              = 'SalesOrder.Picked';
    public const str SOShippingEvent            = 'SalesOrder.Shipping';
    public const str SOConfirmationError        = 'SalesOrder.ConfirmationError';
    public const str SOPickedErrorEvent         = 'SalesOrder.PickError';
    public const str SOShippingErrorEvent       = 'SalesOrder.ShippingError';
    public const str SOReserveErrorEvent        = 'SalesOrder.ReservationError';
    public const str SOReserveInfoEvent         = 'SalesOrder.Reservation'; 
}
